head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/GANTT/data/GANTT_SCHEDULE.json";   // {type:gantt, json:[{rangex,rangey,plan}]}
scwin.CHART_CONFIG = {
    global: {   // 전역 설정(색/크기/애니메이션/이벤트)
        bUserConf: true,
        onclick: function (x) { scwin.click("클릭: " + (x && x.label ? x.label : "")); }   // 클릭 이벤트 콜백
    },
    axis: {   // 축 설정
        x: { show: false, type: "category", tick: { line: { show: false } } },
        y: { show: false, tick: { line: { show: false } } }
    },
    tooltip: {   // 툴팁
        noUseExpand: true,
        custom: function (data) {   // 커스텀 렌더 함수
            return "<div style='color:#fff;padding:8px;'>" +
                   "<b>" + data.label + "</b><br/>시간대: " + data.y_start + " ~ " + data.y_end + "</div>";
        }
    },
    extend: {   // 차트별 세부 옵션
        gantt: {   // 간트 전용 옵션
            header: {
                headerHeight: 20,
                headerJson: [
                    { h_id: "h0", start: "0",   end: "0.6", fillColor: "#eef2f7", text: "시간", fontSize: "11", strokeColor: "#ccc" },
                    { h_id: "h1", start: "0.6", end: "1.6", fillColor: "#eef2f7", text: "월",   fontSize: "11", strokeColor: "#ccc" },
                    { h_id: "h2", start: "1.6", end: "2.6", fillColor: "#eef2f7", text: "화",   fontSize: "11", strokeColor: "#ccc" },
                    { h_id: "h3", start: "2.6", end: "3.6", fillColor: "#eef2f7", text: "수",   fontSize: "11", strokeColor: "#ccc" },
                    { h_id: "h4", start: "3.6", end: "4.6", fillColor: "#eef2f7", text: "목",   fontSize: "11", strokeColor: "#ccc" },
                    { h_id: "h5", start: "4.6", end: "5.6", fillColor: "#eef2f7", text: "금",   fontSize: "11", strokeColor: "#ccc" }
                ]
            },
            yAxisValueMargin: 0.000000001,
            gridX: { show: false },
            gridY: { show: false },
            labelFormat: function (d) { return d.label; },
            label: { moveY: 10 },   // 라벨
            useWheelScrollY: true,
            useFreeYPosition: true
        }
    }
};

scwin.onpageload = async function () {
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const data = res.responseJSON;
    $c.ext.drawChartData("gantt", data, chartWrap, scwin.CHART_CONFIG);
};
scwin.click = function (msg) { 
	$c.win.alert(msg)
};
